OUT=Path(__file__).parent
PDF=Path('C:/Users/kylej/AppData/Local/Temp/B2W-2819U-12_02.pdf')
SHA='54b246fb2956c8970193b54cce160544ece74a7259169a188b6aacd8c9dd4608'
URL='https://library.ymcapps.net/library/om/contents/pdf/10/B2W-2819U-12_02.pdf'
def sha(p):return hashlib.sha256(p.read_bytes()).hexdigest()
def save(p,d):p.write_text(json.dumps(d,ensure_ascii=False,indent=2)+'\n',encoding='utf-8')
assert sha(PDF)==SHA
DEST=OUT/'lower-engine-bench-v1.procedure.json'
assert not DEST.exists() or json.loads(DEST.read_text(encoding='utf-8'))['publication_status']!='APPROVED'
steps=[]
def step(i,title,pages,instruction,verification,record=False,diagram=True):
 steps.append(dict(id=i,title=title,instruction=instruction,source_pdf_pages=pages,source_links=[URL+'#page='+str(p) for p in pages],verification=[verification],record_required=record,diagram_reference_required=diagram,depends_on=[steps[-1]['id']] if steps else [],origin='Original authored summary of exact US 2022 OEM procedure and diagrams; no year inheritance.'))
step('entry','Accept the prepared lower engine',[21,223,232,249], 'Confirm this is the stock US 2022 YZ450F engine, cold, drained and securely supported off the bike. Cams, head, cylinder and piston are already removed and indexed; the chain is retained. External clutch cable, coolant, exhaust, electrical and drive connections are disconnected. This route retains sound cases, water-pump internals, starter motor and stator mountings. Resolve faults in those excluded assemblies before proceeding. Arrange exact top-end closure, engine refitting and commissioning separately.', 'Record identity, drained condition, removed top end and retained-system condition.',True)
step('generator-cover-out','Open the generator side',[223,224], 'Remove the shift pedal if still fitted and the seven left-cover bolts, retaining the lead holder in its indexed position. Lift the cover with its stator and sensor mountings intact; collect both dowels and discard the gasket. Support the cover and leads without strain. Remove the rotor nut and washer, extract the rotor with 90890-04151 / YM-04151 and recover the Woodruff key. Do not strike the crankshaft or disturb the stator screws.', 'Cover, dowels, key and rotor stored without lead or taper damage.')
step('clutch-out','Remove the coil-spring clutch pack',[232,233,239], 'Remove the clutch-cover bolts and cover, discarding its O-ring. Release the six spring bolts progressively across the pressure plate; collect springs, pressure plate, push rod 1, its bearing/washer/circlip, ball and push rod 2. Keep the eight friction and seven steel plates in their original order for inspection. ', 'Six springs and all release/plate parts indexed.')
step('boss-out','Remove the clutch boss and basket',[232,233,235], 'Straighten the clutch-boss lockwasher tab. Hold the boss with 90890-04199 / YM-91042, remove the nut and discard the lockwasher. Remove the boss, thrust washer and primary driven gear/basket, preserving their orientation. Remove the push-lever shaft carefully from its seal and bearings.', 'Boss stack and push-lever shaft accounted for.')
step('right-cover-out','Remove the right cover and filter',[90,234], 'Remove the oil-filter cover, filter and O-rings. Remove radiator pipe 2 from the right-cover interface and discard its O-ring. Remove the right-cover bolts and lift the cover without forcing the water-pump shaft drive. Keep the pump assembled to the cover. Recover the dowels and collar; discard the cover gasket and collar O-ring. Index the cover fasteners using the exploded view.', 'Right cover, pipe, filter, dowels and collar removed and indexed.')
step('starter-out','Lift out the starter drive',[226,227], 'Remove the two starter-drive holder bolts, holder, washer and damper assembly. Lift out the starter-clutch assembly, keeping its drive gear, bearings, washer and dowels in the illustrated order. Keep the starter motor intact.', 'All starter-drive spacers and bearings indexed to the exploded view.')
step('shift-out','Remove the external selector mechanism',[240,241,242], 'Remove the shift shaft with collar, spring and roller, then the shift guide and lever assembly. Keep both pawls, pins and springs indexed. Remove the stopper lever, collar and spring. To loosen the segment bolt, turn the segment counterclockwise to its stop; avoid impact on the segment or stopper lever. Remove the segment. Remove the shift-shaft seal for renewal without damaging the bore.', 'Selector pieces indexed; no impact damage.')
step('drive-out','Remove the primary and balancer drives',[245,246], 'Straighten the balancer and balancer-weight lockwasher tabs. Place an aluminum plate between the balancer drive and weight gear teeth at the illustrated contact. Loosen the balancer nut, primary-drive nut and balancer-weight-gear nut. Remove the balancer, straight key, primary gear, conical washer, drive gear and weight gear in the illustrated order. Discard both lockwashers and the conical washer. Keep the weight plate assembled to its gear.', 'Key, gears and washer positions indexed; holding plate removed.')
step('pump-out','Remove and open the oil pump',[244,246], 'Remove the oil-pump assembly bolts. Lift out the pump, remove its cover bolt and separate cover, outer rotor, dowel pin, inner rotor and drive shaft. Keep the dowel pin contained and preserve all orientations.', 'Pump components indexed and clean.')
step('chain-out','Assess the timing drive before selecting a crank',[249,251,254], 'Remove the timing-chain guide stopper plate, exhaust-side guide and chain. Check for chain stiffness and guide wear or damage. A stiff chain requires replacement of the camshaft sprocket, chain and crankshaft sprocket as a set; a damaged crank sprocket requires a complete crankshaft replacement. Record the matched timing-drive decision now and coordinate the necessary cam/sprocket work with top-end closure. Replace a damaged or worn guide.', 'Timing-chain/guide condition and any matched replacement requirements recorded before crank selection.',True)
step('cases-open','Separate the crankcase halves',[249,251], 'Index all twelve case bolts: five 45 mm, four 60 mm and three 75 mm at their exact map positions. Loosen each a quarter-turn at a time before removing them. Lay the engine left side down. Use only the designated splitting slit for a screwdriver tip, with light soft-hammer taps on reinforced splitting or mounting bosses. Lift the right case evenly, leaving crank and gearbox in the left. If separation resists, find the remaining bolt or fitting; do not force or strike a gasket surface. Collect dowels and any O-ring encountered.', 'Cases separated evenly; fasteners and locating pieces accounted for.')
step('transmission-out','Remove the gearbox as an indexed group',[256,257], 'Record each fork location and direction. Remove both guide bars, all four springs, shift cam and the L/C/R forks. Remove main and drive axles together, lightly tapping the drive axle with a soft hammer if needed. Preserve the collar initially installed in the case. Keep every gear, washer and clip indexed before further disassembly.', 'Fork and gear-stack orientations recorded.',True)
step('crank-out','Remove the balancer shaft and crank',[253,254], 'Turn the balancer shaft so its flat faces the crank and remove it. Use separator 90890-04152 / YU-A9642 at the illustrated mounting positions to remove the crankshaft assembly. Support the case and do not drive the crank out with blows.', 'Crank and balancer shaft removed without case damage.')
step('case-clean','Clean and inspect the retained cases',[21,22,250,251], 'Remove the oil nozzle for cleaning and keep its direction indexed. Clean the cases with mild solvent and remove old gasket material without cutting the sealing faces. Inspect for cracks or damage; this route requires sound retained cases. Clear blocked oil passages with controlled compressed air, never spinning bearings with air. Remove solvent and loose debris and dry the cases before assembly.', 'Case condition and clear, dry oil passages accepted.',True)
step('bearings','Renew case bearings where required',[21,22,250,251,252], 'Inspect the case bearings for damaged or rough operation. For renewal, remove the exact retainers shown, press the old bearing out through its inner race and discard it. Install the correct new bearing parallel by pressing its outer race, with manufacturer markings outward; lubricate the illustrated bearings with engine oil. Fit the exact retainer to each position: crankshaft bearing plates 22 Nm with LOCTITE, other bearing plates 12 Nm with LOCTITE; the separate illustrated upper collar holder is 10 Nm with LOCTITE. Preserve the distinct plate and bolt locations.', 'Record renewed bearings, seating and retainer torques against the case diagram.',True)
step('case-seals','Fit the crankcase seals and collars',[21,22,250,252], 'Install new case seals with LS grease at the illustrated lips and new circlips where removed. Keep the main seal lip toward the oil chamber and marked faces outward unless a dedicated instruction states otherwise. Set the left drive-axle seal at the illustrated 0.0–0.5 mm depth. Preserve the upper seal, collar and circlip stack shown in the case exploded view; do not transfer later-model flush or fixed-depth dimensions.', 'Record left seal depth and confirm both seal/retainer stacks.',True)
step('crank-check','Measure the crank assembly',[254], 'Turn the supported crank slowly and measure runout at the illustrated points; limit 0.030 mm. Measure assembly width at the illustrated faces; required range 61.93–62.00 mm. Replace the complete crank if either fails or its sprocket is damaged. Clear a blocked journal oil passage with compressed air, then remove contamination. This route does not press apart or rebuild the connecting rod.', 'Actual runout, width, sprocket condition and crank disposition recorded.',True)
step('gearbox-check','Inspect shafts, gears and selector parts',[257,258], 'Measure main- and drive-axle runout using centers and a dial gauge; limit 0.08 mm for each. Replace gears with blue discoloration, pitting, wear, damaged or rounded dogs, or rough movement. Replace forks with bent, scored or worn followers/pawls. Roll guide bars on a flat surface; replace bent bars without straightening. Rough fork movement requires fork and bar replacement as a set. Replace a damaged or worn shift drum/segment assembly.', 'Shaft readings and each failed part/replacement decision recorded.',True)
step('main-build','Build the main-axle stack',[22,256,258,259], 'Follow the exact exploded view for all washers and new circlips. On the main axle install fifth pinion 21T, third pinion 20T, collar, fourth pinion 22T and second pinion 15T in the illustrated order. Apply molybdenum-disulfide oil to idler-gear inner/end surfaces and sliding-gear inner surfaces. Set new circlip sharp corners away from the adjacent washer/gear, with both ends evenly on spline crests; do not over-expand clips.', 'Exact 2022 main-axle stack and each new clip seated.')
step('drive-build','Build the drive-axle stack',[22,256,258,259], 'Install the collar, second wheel 23T, fourth wheel 24T, third wheel 26T, fifth wheel 20T, collar and first wheel 27T on the drive axle using the exploded washer/clip positions. Apply molybdenum-disulfide oil to idler/collar inner and end faces and sliding-gear inner faces. Fit a new drive-axle O-ring with LS grease. Use new circlips with the same sharp-edge and spline-crest orientation just checked.', 'Exact drive-axle stack, new O-ring and clips seated.')
step('crank-in','Install the accepted crank and balancer shaft',[253,254,255], 'Apply LS grease to seal lips and molybdenum-disulfide grease at the illustrated crank location. Draw the crank into the left bearing using pot 90890-01274 / YU-90058, bolt 90890-01275 / YU-90060, M12 adapter 90890-01278 / YU-90063 and spacer 90890-04081 / YM-91044. Hold the rod at TDC while turning the installer until the crank bottoms against the bearing. Refit the balancer shaft with its flat toward the crank for clearance; do not force it.', 'Crank fully seated with free movement and balancer shaft in position.')
step('transmission-in','Fit the gearbox and forks',[256,259,260], 'LS-grease the case seal lip and install its collar with slit toward the crankcase, protecting the lip. Oil the main/drive axle bearings and fit both shafts into the left case together. Oil fork grooves, shift-cam grooves and bearing-contact surface. Fit fork L to the fourth wheel, fork R to the fifth wheel and fork C to the third pinion; engage their followers with the shift cam as illustrated.', 'L/C/R engagement and collar slit match the exact diagram.')
step('shift-bars-in','Check the assembled gearbox',[256,260], 'Lightly screw each of the four springs into its guide-bar end beforehand. Oil both guide bars and install long and short bars at their exact positions. Operate the shift cam, forks and transmission through the gear positions. Correct rough or incomplete operation before closing the cases.', 'Actual selector and gearbox movement accepted and recorded.',True)
step('cases-close','Seal and close the crankcase',[249,252], 'Fit the oil nozzle in its indexed orientation and tighten its bolt to 10 Nm with LOCTITE. Confirm no tools, rags, solvent or debris remain. Apply Yamaha/ThreeBond 1215 to the illustrated mating path. Install dowels and fit the right half with the rod at TDC, using only light soft-hammer taps. Restore all five 45 mm, four 60 mm and three 75 mm bolts to the exact map. Tighten in a crisscross pattern in two stages with quarter-turn increments to 12 Nm. Confirm crank and gearbox still move freely.', 'Case fastener map, 12 Nm closure, nozzle 10 Nm LT and free movement recorded.',True)
step('chain-in','Restore the accepted timing chain',[249,251,254], 'Install the accepted or matched replacement chain and exhaust guide. Fit the guide stopper plate with LOCTITE and tighten to 10 Nm. Retain the chain above the open cylinder mouth so it cannot fall or jam. Carry any matched cam/sprocket replacement requirement into top-end work.', 'Chain retained and matched-drive disposition carried forward.')
step('pump-build','Inspect and rebuild the oil pump',[244,246,247], 'Inspect pump cover, drive shaft and housing for cracks, wear or damage; replace the complete pump for defects. Oil the shaft and inner rotor, seat the dowel in the inner-rotor groove, then fit the oiled outer rotor. Install the cover bolt at 6 Nm with LOCTITE, then the pump assembly bolts at 5 Nm with LOCTITE. Confirm smooth pump movement after tightening; a rough pump requires reassessment or assembly replacement.', 'Pump condition and final smooth operation recorded.',True)
step('drives-check','Accept the primary and balance drives',[236,246], 'Inspect primary drive and driven gears for damage, wear, prior excessive noise and mutual free play. Failure of either primary gear, excess noise or free play requires both primary gears as a set. Separately replace worn/damaged balance gears and a cracked/damaged balancer. Keep a sound balance-weight plate attached to its gear.', 'Primary pair and balance-drive dispositions recorded.',True)
step('balance-marks','Time the balance gears',[247], 'Align the lower splines of the balancer weight gear and shaft. Fit the balancer drive gear with its lower spline aligned to the crankshaft lower spline, while matching the punched marks of both gears. Use the two detailed views to distinguish spline alignment from the gear-tooth timing marks.', 'Both lower-spline alignments and punched timing marks recorded.',True)
step('drive-nuts','Secure the primary and balance drives',[22,245,248], 'Fit a new balance-weight lockwasher and its nut. Fit the primary gear, new conical washer with convex face outward, and primary nut. Fit the straight key, balancer and its new lockwasher/nut. Oil primary-nut threads/contact face and both conical-washer contact faces. Hold the gears only with the illustrated aluminum plate. Tighten weight-gear nut 50 Nm, primary nut 80 Nm and balancer nut 45 Nm. Bend the lockwasher tabs against nut flats and remove the holding plate.', '50/80/45 Nm, oil preparation, new washer directions and locked tabs recorded.',True)
step('shift-restore','Rebuild the selector mechanism',[240,241,242], 'Check shaft, spring, roller, guide, lever, pawls/pins and springs for bends, damage or wear and renew failed parts. Install stopper spring, collar and lever; tighten its bolt to 10 Nm with LOCTITE. Align segment notch to drum pin and install while pushing the stopper lever down; tighten segment bolt to 30 Nm without impact. Oil pawls, pins and springs, assemble them into the lever and fit lever/guide together. Tighten guide bolts to 10 Nm with LOCTITE.', 'Selector condition and 10 LT/30/10 LT fastenings accepted.',True)
step('shift-shaft','Refit the selector shaft and seal',[21,22,240,242,243], 'Fit the roller, shaft spring and collar, oil the shift shaft and slide it into position. Install a new shift-shaft seal with LS grease on its lip, using the exact seal direction and general marked-face rule. Align pedal and shaft punch marks when refitting the pedal and tighten its bolt to 12 Nm. Confirm selection works freely.', 'Shaft/seal and punch marks correct; 12 Nm pedal closure.')
step('starter-check','Inspect and refit the starter drive',[21,226,227], 'Inspect the starter clutch and drive gear for burrs, chips, roughness or wear and its gear for damage or pitting; renew the failed assembly. Viewed exactly as the operation diagram, the drive gear must turn freely counterclockwise and engage the clutch clockwise. Oil bearings before installation. Restore the indexed assembly, bearings, washers, damper, dowels and holder from the exploded view; holder bolts 12 Nm with LOCTITE. Do not omit the washer behind the holder.', 'Directional test, part disposition and holder closure recorded.',True)
step('release-inspect','Inspect the mechanical clutch release',[235,236,237], 'Check push-lever shaft, both push rods, bearing, washer and ball for wear, cracks or damage. Measure push rod 2 bending; limit 0.10 mm. Renew failed parts. This route retains sound push-lever bearings; failed bearings require their separate supported repair before closure. Keep the accepted release-shaft bearings and seal protected. Remove the separate right-cover internal oil seal, washer and circlip for renewal as illustrated.', 'Release-part condition and push-rod bending recorded.',True)
step('release-seal','Renew the right-cover internal oil seal',[22,234,236,237], 'Fit a new right-cover internal oil seal parallel with its manufacturer marks or numbers facing inward, overriding the general outward-mark rule at this particular seal. Apply LS grease to its lip, then install the washer and a new circlip fully in its groove.', 'Seal inward-mark orientation, washer and new circlip seated.')
step('right-cover-in','Close the right crankcase cover',[234,237], 'Fit the dowels, new LS-greased collar O-ring, collar and new gasket. Oil the water-pump impeller-shaft end and align it with the balancer end slot before seating the cover. Do not pull a misaligned shaft home with bolts. Restore the right-cover bolts and tighten progressively across the cover to 10 Nm. Oil both push-lever bearings and LS-grease its seal lip before refitting the shaft.', 'Pump drive aligned and cover seated before 10 Nm tightening.')
step('pipe-filter','Refit the coolant pipe and oil filter',[90,234], 'Fit radiator pipe 2 with a new O-ring lubricated with LS grease, following the illustrated joint orientation; tighten the joint bolt to 10 Nm. Install a new oil filter and new LS-greased cover O-rings, then the filter cover at 10 Nm. Keep oil and coolant unfilled at this bench stage.', 'Pipe and filter sealed with new O-rings; both closures 10 Nm.')
step('clutch-inspect','Measure the coil-spring clutch',[235,236], 'Measure every friction plate at four points: nominal 2.92–3.08 mm, wear limit 2.82 mm. Damage or wear requires the friction set replaced. Check steel plates for damage and flat-plate/feeler-gauge warpage; limit 0.10 mm, replacing the steel set if failed. Measure all six springs: standard 48.00 mm, minimum 45.60 mm; replace the spring set for damage or failed length. Inspect boss splines, housing dogs and pressure plate. Replace a damaged pressure plate or boss; renew a worn/damaged housing as needed rather than using an unspecified deburring allowance.', 'Plate measurements, warpage, spring lengths and part decisions recorded.',True)
step('clutch-base','Install the clutch basket and boss',[232,233,237], 'Oil the primary driven gear/basket inner circumference. Fit it, the thrust washer and clutch boss in the illustrated order. Fit a new lockwasher with its notch engaged with the boss rib.', 'Basket, thrust washer, boss and new notched lockwasher correctly seated.')
step('clutch-nut','Secure the clutch boss',[232,238], 'Oil the clutch-boss nut threads and contact surface. Hold the boss with 90890-04199 / YM-91042 and tighten the nut to 75 Nm. Bend the new lockwasher tab firmly along a nut flat. ', 'Actual 75 Nm, oil preparation and bent locking tab recorded.',True)
step('clutch-pack','Install the exact friction-plate order',[232,238], 'Oil every friction and steel plate. Working outward from the boss, alternate frictions and steels: three black type-1 frictions, then three purple type-2 frictions, then two black type-1 frictions. Seven steel plates sit between the eight frictions, beginning and ending the pack with friction plates. Confirm identification colors and order against the exploded view.', 'Five black plus three purple frictions and seven steels correctly alternated.')
step('pressure-plate','Restore the release rods and six springs',[22,232,238,239], 'Oil and assemble push rod 1, its bearing and washer with a new circlip. Oil push rod 2 and ball; fit rod 2, ball and rod 1 in the illustrated order. Fit the pressure plate and six accepted springs. Tighten spring bolts progressively in a crisscross pattern to 10 Nm. ', 'Ball, both rods, new circlip, six springs and 10 Nm closure confirmed.')
step('clutch-cover','Close the clutch cover',[232,239], 'Fit a new clutch-cover O-ring with LS grease, seat the cover and tighten its bolts progressively in a crisscross pattern to 10 Nm.', 'New lubricated O-ring and 10 Nm cover closure.')
step('rotor-in','Inspect and refit the rotor',[223,224,225], 'Inspect rotor inner and stator outer surfaces. Contact damage requires crank-runout and bearing reassessment before proceeding. Replace a damaged key. Clean both mating tapers, install the key with its flat parallel to the crank centerline, then align the rotor keyway to it. Fit washer and nut, tightening to 65 Nm using the illustrated holding flats. Keep intact stator and sensor screws undisturbed.', 'Rotor clearance, key alignment and 65 Nm recorded.',True)
step('generator-cover-in','Close the generator cover',[223,225], 'Install both dowels and a new left-cover gasket. Fit the supported cover with intact stator and sensor mountings, protecting the leads and restoring the external lead holder at its illustrated bolt position. Tighten the seven cover bolts in stages and a crisscross pattern to 10 Nm. Leave bike-level coupler routing to the exact engine-refit procedure.', 'New gasket, dowels, lead holder and 10 Nm closure confirmed.')
step('exit','Record the lower-engine handoff',[249,252,260], 'Record the accepted crank, gearbox, clutch, pump and starter-drive work. Confirm free crank/gearbox movement and account for all tools, holding plates and loose parts. The timing chain remains retained above the open cylinder mouth. Continue the exact 2022 top-end installation, then engine refitting and post-rebuild commissioning; carry any matched cam/chain/crank replacement requirements forward. Do not run this unfilled, open-top-end engine.', 'Lower-engine work and outstanding top-end, fluids, oil-flow checks and commissioning recorded.',True)
pages=sorted({p for s in steps for p in s['source_pdf_pages']})
labels={21:'1-9',22:'1-10',90:'3-14'};labels.update({p:'5-'+str(p-186) for p in range(223,261)})
d=dict(schema_version=1,id='yamaha-2022-yz450f-lower-engine-bench-v1',target=dict(manufacturer='Yamaha',model='YZ450F',model_year=2022,region='US',variant='standard'),scope_confirmed=True,title='Rebuild the stock lower engine on the bench',status='SOURCE_REVIEWED_BOUNDED_PROCEDURE',publication_status='PENDING_INDEPENDENT_REVIEW',completeness='Continuous bounded lower-engine route from prepared bench engine through case/crank/gearbox, primary and balance drives, coil-spring clutch, oil pump and starter-drive closure. Top-end assembly, bike refitting and commissioning remain separate.',applicability=dict(included='Exact stock US 2022 YZ450F with serviceable retained cases and retained water-pump/stator/starter-motor internals.',excluded=['Pressed connecting-rod/crank internal rebuild','Damaged case-set replacement or machining','Water-pump, starter-motor or stator electrical internal rebuild','Failed retained push-lever bearings','Top-end removal/refit, engine/frame installation, fluid filling and running'],year_inheritance='NONE'),affected_components=['engine','crankshaft','transmission','clutch','oil_pump'],entry_state=['Engine cold, removed, fully drained and securely supported.','Cams, head, cylinder and piston removed; all external interfaces disconnected and parts indexed.'],exit_state=['Cases, lower drives, coil-spring clutch and side covers assembled; accepted gearbox/crank movement.','Top end remains removed; engine refitting, fluids and commissioning remain outstanding.'],preflight=['Arrange exact 2022 top-end and bike-level closure before teardown.','Have the exact 2022 case-bearing, bolt-length, gear-stack, balance-timing and clutch diagrams available.','Resolve failed excluded retained assemblies before starting.'],required_tools=[dict(name=x) for x in ['Secure engine fixture, clean trays and chain-retaining wire','Calibrated torque tools covering 5–80 Nm; hand sockets, holding spanner and circlip tools','Rotor puller 90890-04151 / YM-04151; clutch holder 90890-04199 / YM-91042','Crank separator 90890-04152 / YU-A9642; installer pot01274/bolt01275/M12adapter01278/spacer04081 and listed exact equivalents','Parallel bearing press/drivers, depth gauge, soft hammer and aluminum gear-holding plate','Dial gauge with centers, micrometer, flat plate, feeler gauge and caliper','Mild solvent and controlled compressed air']],required_parts=[dict(name=x) for x in ['Exact stock replacement assemblies/parts selected by inspection; eight-friction/seven-steel clutch and six springs','New gaskets, O-rings, oil seals, circlips, three lockwashers and primary conical washer','New oil filter and cover O-rings; radiator-pipe O-rings','Engine oil; molybdenum-disulfide oil and grease; lithium-soap-based grease','Yamaha/ThreeBond 1215 and LOCTITE locking agent at the specifically cited joints; exact OEM does not identify a LOCTITE grade']],critical_stop_conditions=['Failed retained case or excluded assembly.','Failed measurements, stiffness, incorrect timing or incomplete selector engagement.','Ambiguous part orientation, missing hardware, foreign material or forced assembly.'],operation_dependencies=[],source=dict(source_url=URL,document_sha256=SHA,document_revision='B2W-2819U-12 / LIT-11626-35-03; YZ450FN 2022',pdf_pages=pages,printed_pages=[labels[p] for p in pages],review_status='PENDING_INDEPENDENT_REVIEW',review_note='Exact 2022 OEM text and critical exploded/assembly diagrams reviewed; independent review pending.'),steps=steps)
save(DEST,d)
